MAKE CODE: Toggle LED
language arduino
bool ledOn = false;
int last = HIGH;

void setup() {
  pinMode(2, INPUT_PULLUP);
  pinMode(13, OUTPUT);
}

void loop() {
  int now = digitalRead(2);
  if (now == LOW && last == HIGH) {
    ledOn = !ledOn;
  }
  last = now;
  digitalWrite(13, ledOn ? HIGH : LOW);
}
END

