MAKE CODE: Servo sweep
language arduino
#include <Servo.h>

Servo myServo;
int pos = 0;

void setup() {
  myServo.attach(9);
}

void loop() {
  for (pos = 0; pos <= 180; pos += 1) {
    myServo.write(pos);
    delay(15);
  }
  for (pos = 180; pos >= 0; pos -= 1) {
    myServo.write(pos);
    delay(15);
  }
}
END

MAKE CODE: Sweep
language arduino
#include <Servo.h>

Servo s;
int angle = 0;
int step = 1;

void setup() {
  s.attach(9);
}

void loop() {
  s.write(angle);
  angle += step;
  if (angle >= 180 || angle <= 0) {
    step = -step;
  }
  delay(15);
}
END

