Servo arm;

void setup() {
  arm.attach(9);
}

void loop() {
  for (int i = 0; i <= 360; i++) {
    int a = (i <= 180) ? i : 360 - i;   // up to 180, then back to 0
    arm.write(a);
    delay(15);
  }
}
END

MAKE CODE: Back and forth
language arduino
#include <Servo.h>
Servo servo;
int pos = 0;
bool up = true;

void setup() { servo.attach(9); }

void loop() {
  servo.write(pos);
  delay(15);
  if (up) { pos++; if (pos >= 180) up = false; }
  else { pos--; if (pos <= 0) up = true; }
}
END

