MAKE CODE: Pump for 10 s
language st
PROGRAM PumpTimer
VAR
    StartButton AT %IX0.0 : BOOL;
    Pump AT %QX0.0 : BOOL;
END_VAR
VAR
    Running : BOOL;
    RunTimer : TON;
END_VAR

IF StartButton AND NOT Running THEN
    Running := TRUE;
END_IF;

RunTimer(IN := Running, PT := T#10S);

IF RunTimer.Q THEN
    Running := FALSE;
END_IF;

Pump := Running;
END_PROGRAM
END

